-- Coastal Clash civic corpus: paste into a Snowsight worksheet and Run All.
USE WAREHOUSE COMPUTE_WH;

CREATE DATABASE IF NOT EXISTS COASTAL_CLASH;

CREATE SCHEMA IF NOT EXISTS COASTAL_CLASH.CORPUS;

CREATE TABLE IF NOT EXISTS COASTAL_CLASH.CORPUS.ISSUES (
    ID STRING PRIMARY KEY, TITLE STRING, AREA STRING, SCOPE STRING, CATEGORY STRING, YEARS STRING, SUMMARY STRING,
    FACTS VARIANT, SIDES VARIANT, TENSIONS ARRAY, CONCERNS ARRAY, CARD_IDEAS ARRAY, VERIFICATION VARIANT,
    REVIEW_STATUS STRING DEFAULT 'unreviewed', RETRIEVED_AT DATE, LOADED_AT TIMESTAMP_LTZ);

CREATE TABLE IF NOT EXISTS COASTAL_CLASH.CORPUS.SOURCES (ISSUE_ID STRING, TITLE STRING, OUTLET STRING, URL STRING, KIND STRING);

MERGE INTO COASTAL_CLASH.CORPUS.ISSUES t
   USING (SELECT f.value AS v FROM TABLE(FLATTEN(INPUT => PARSE_JSON($$[{"id":"west-ave-road-raising","title":"West Avenue road raising and stormwater","area":"west-avenue","scope":"area","category":"flooding","years":"2018-2025","summary":"The city is raising West Avenue streets by up to about two feet with new drainage, pumps, water and sewer lines. Most residents refused liability-release harmonization agreements, and nearby businesses objected to lost parking and construction disruption.","facts":["Streets raised by as much as two feet","Total budget about $100 million to $105 million (the city's English and French project pages list different figures)","Construction on a block began in June 2025 (NBC6)"],"sides":[{"who":"City of Miami Beach","position":"Raising roads and adding drainage protects against king tide and storm flooding"},{"who":"Residents","position":"Raised roads may push water onto private property; most refused harmonization agreements"},{"who":"Businesses","position":"Lost parking and construction hurt daily business"}],"tensions":["raise-the-street-vs-homes-below","infrastructure-side-effects"],"concerns":["flooding","construction-disruption","parking","liability"],"card_ideas":["drainage-upgrade","elevate-buildings","neighborhood-petition","harmonization-deal"],"sources":[{"title":"West Avenue Neighborhood Enhancements","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/projects/west-avenue-neighborhood-improvements-project-phase-ii/","kind":"official"},{"title":"Miami Beach wants higher roads and pumps to fight sea rise. Some residents say no way","outlet":"WLRN","url":"https://www.wlrn.org/environment/2018-05-17/miami-beach-wants-higher-roads-and-pumps-to-fight-sea-rise-some-residents-say-no-way","kind":"news"},{"title":"Controversy arising in Miami Beach over raising roads to combat flooding","outlet":"Local10","url":"https://local10.com/news/local/2022/02/21/controversy-arising-in-miami-beach-over-raising-roads-to-combat-flooding","kind":"news"},{"title":"Miami Beach resiliency project brings flood protection and frustration","outlet":"NBC6","url":"https://www.nbcmiami.com/investigations/miami-beach-resiliency-project-brings-flood-protection-and-frustration-for-lincoln-road-business/3756786/?amp=1","kind":"news"}],"verification":{"status":"resolved","notes":["Budget differs between the English ($105,140,819) and French ($100,229,771) versions of the city project page"],"resolution":"Stated as a range and named the discrepancy instead of picking one figure."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"first-street-stormwater","title":"First Street and South Pointe stormwater project","area":"south-pointe","scope":"area","category":"flooding","years":"2020-2026","summary":"First Street between Alton Road and Washington Avenue will be rebuilt and raised to at least 3.7 ft NAVD with a new pump station at First Street and Washington Avenue. The community rejected an earlier pump site; raising Alton Road and South Pointe Drive was deferred for budget reasons.","facts":["Road raised to a minimum of 3.7 ft NAVD","Total budget $60 million","Phases 1 and 2 funded; in design as of February 2026, with construction expected to start in 2026-2027","Pump station at the southeast corner of First Street and Washington Avenue"],"sides":[{"who":"City of Miami Beach","position":"Reduce flood risk, speed recovery after storms, cut flood-related business losses"},{"who":"South of Fifth residents","position":"Rejected the pump station site at First Street and Alton Road; asked about parking, garage backflow and flood insurance"}],"tensions":["infrastructure-side-effects","budget-tradeoff"],"concerns":["flooding","infrastructure-location","parking","cost"],"card_ideas":["drainage-upgrade","emergency-funding","neighborhood-petition"],"sources":[{"title":"First Street Neighborhood Improvements & South Pointe Stormwater Project","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/projects/1-street-between-alton-road-and-washinton-avenue/","kind":"official"},{"title":"First Street Neighborhood Improvement Community Survey Results (LTC 310-2022)","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/wp-content/uploads/2022/08/LTC-310-2022-First-Street-Neighborhood-Improvement-Community-Survey-Results.pdf","kind":"official"}],"verification":{"status":"resolved","notes":["City page gives both 2026 and 2027 as the construction start"],"resolution":"Construction start stated as 2026-2027 because the city page gives both years."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"sunset-harbour-raising","title":"Sunset Harbour streets raised above shop floors","area":"west-avenue","scope":"area","category":"flooding","years":"2016-2020","summary":"Sunset Harbour streets were raised two to three feet above adjacent building floors. Some shops were left below grade and reported losing flood coverage as basements, while a consultant found nearby condos gained value.","facts":["Streets raised two to three feet above adjacent building floors","Consultant estimated an 11.9% value gain for more than 1,300 condos after the 2016 upgrade"],"sides":[{"who":"City and consultant","position":"Elevated streets and pumps raised property values"},{"who":"Business owners","position":"Buildings left below the road became uninsurable basements"}],"tensions":["raise-the-street-vs-homes-below"],"concerns":["flooding","insurance","property-value"],"card_ideas":["drainage-upgrade","elevate-buildings","harmonization-deal"],"sources":[{"title":"Miami Beach lifts roads due to sea rise, floods nearby homes","outlet":"Governing","url":"https://www.governing.com/community/miami-beach-lifts-roads-due-to-sea-rise-floods-nearby-homes","kind":"news"},{"title":"Can raising roads for sea rise make a Miami Beach home more valuable?","outlet":"National Mortgage News","url":"https://www.nationalmortgagenews.com/articles/can-raising-roads-for-sea-rise-make-a-miami-beach-home-more-valuable","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"palm-hibiscus-raising","title":"Palm and Hibiscus Islands road raising","area":"new-area","scope":"new-area","category":"flooding","years":"2018-2021","summary":"A $40.9 million road raising and drainage project on Palm and Hibiscus Islands drew an inspector general report on permit problems and cost overruns. Residents described inaccessible garages and steep driveways, and property owners sued over flooding blamed on raised roads.","facts":["$40.9 million project","Inspector general found permit problems and cost overruns"],"sides":[{"who":"Residents","position":"Roads so high garages are inaccessible and lawns flood while streets stay dry"},{"who":"Property owners (lawsuit)","position":"Raised road sent floodwater onto their property"}],"tensions":["raise-the-street-vs-homes-below","costs-on-owners"],"concerns":["flooding","cost","liability"],"card_ideas":["elevate-buildings","neighborhood-petition","harmonization-deal"],"sources":[{"title":"Miami Beach is raising roads for sea rise. Lawsuits say they're causing flooding too","outlet":"WUSF","url":"https://www.wusf.org/environment/2021-11-13/miami-beach-is-raising-roads-for-sea-rise-lawsuits-say-theyre-causing-flooding-too","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"king-tide-pumps-2014","title":"The 2014 king tide pump program","area":"citywide","scope":"citywide","category":"flooding","years":"2014-2017","summary":"Miami Beach began a pump and drainage program in 2014. South Beach stayed largely dry in the fall 2014 king tides, but critics questioned where pumps went first, and in 2017 a tropical storm overwhelmed the unfinished system.","facts":["About $500 million more planned over five years (2014)","$15 million spent on the most flood-prone areas by 2014"],"sides":[{"who":"Mayor Philip Levine","position":"Called the 2014 king tide test proof positive that the system can work"},{"who":"Political rival","position":"Questioned why early work protected areas near the mayor's buildings"},{"who":"New Times (2017)","position":"Pumps struggled to keep up with storm rainfall"}],"tensions":["infrastructure-side-effects"],"concerns":["flooding","cost","fairness"],"card_ideas":["drainage-upgrade","emergency-funding"],"sources":[{"title":"Miami uses pumps to battle flooding from sea level rise","outlet":"HPPR / NPR","url":"https://www.hppr.org/2014-10-10/miami-uses-pumps-to-battle-flooding-from-sea-level-rise","kind":"news"},{"title":"Miami Beach floods from Tropical Storm Emily overwhelm sea level rise pumps","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/riptide/2017/08/02/miami-beach-floods-from-tropical-storm-emily-overwhelm-sea-level-rise-pumps","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"stormwater-master-plan-2024","title":"2024 Stormwater Master Plan update","area":"citywide","scope":"citywide","category":"flooding","years":"2024","summary":"The City Commission adopted an update to the 2011 Stormwater Master Plan prioritizing $95 million for 20 critical resilience projects over the next decade.","facts":["$95 million for 20 projects over a decade","$103 million in stormwater projects completed since the 2011 plan"],"sides":[{"who":"City Commission","position":"Prioritize the most critical resilience projects"}],"tensions":["budget-tradeoff"],"concerns":["flooding","cost"],"card_ideas":["drainage-upgrade","emergency-funding"],"sources":[{"title":"Miami Beach Prioritizes $95 Million in Infrastructure Improvements","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/?p=295146","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"indian-creek-drive","title":"Indian Creek Drive (A1A) flood mitigation","area":"collins-mid-beach","scope":"area","category":"flooding","years":"2016-2019","summary":"Indian Creek Drive, a state road, floods at high tide. The city and FDOT partnered to raise the road and seawall, but costs rose and a seawall built too close to the water caused delays.","facts":["Roughly $25-30 million project","City paid about $5.4 million and advanced $20 million to FDOT (2016 agreement)","Tides about 2.2 ft put up to a foot of water over the seawall"],"sides":[{"who":"City and FDOT","position":"Raise the road and seawall, add a greenway barrier"},{"who":"ENR reporting","position":"Engineering failure and permitting delays pushed completion back"}],"tensions":["infrastructure-side-effects","local-vs-state"],"concerns":["flooding","cost","construction-disruption"],"card_ideas":["drainage-upgrade","green-grey-hybrid"],"sources":[{"title":"Discovery of engineering failure leads Miami Beach to flooding fix","outlet":"ENR","url":"https://enr.com/articles/42497-discovery-of-engineering-failure-leads-miami-beach-to-flooding-fix","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"seawall-ordinance-2021","title":"2021 seawall ordinance","area":"citywide","scope":"citywide","category":"flooding","years":"2021","summary":"Miami Beach adopted a seawall ordinance requiring new seawalls at a minimum elevation and giving owners up to 730 days to fix failing walls, with penalties when private seawalls flood neighbors and streets.","facts":["New seawalls at least 5.7 ft NAVD, or 4 ft if designed to rise to 5.7 ft later","Up to 730 days to bring failing seawalls into compliance"],"sides":[{"who":"City Commission","position":"Owners must maintain seawalls so they do not flood neighbors"},{"who":"Waterfront owners","position":"Costs fall on private property owners"}],"tensions":["costs-on-owners"],"concerns":["flooding","cost","liability"],"card_ideas":["elevate-buildings","emergency-funding"],"sources":[{"title":"Miami Beach Commission Adopts First Seawall Ordinance of its Kind","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/?p=149680","kind":"official"}],"verification":{"status":"conflict","notes":["Sources disagree on whether 5.7 ft NAVD applies to private or only public seawalls"]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"hurricane-irma-2017","title":"Hurricane Irma evacuation","area":"citywide","scope":"citywide","category":"flooding","years":"2017","summary":"Before Hurricane Irma, Mayor Philip Levine urged residents and tourists to evacuate the barrier island; causeways were closed and access stayed restricted after the storm.","facts":["Florida's largest evacuation, with more than 30 percent of the state's population asked to leave"],"sides":[{"who":"Mayor Philip Levine","position":"Miami Beach is a barrier island and will be seriously impacted"}],"tensions":["storm-preparedness"],"concerns":["flooding","safety"],"card_ideas":["emergency-funding","drainage-upgrade"],"sources":[{"title":"Miami Beach Mayor Asks Residents To Voluntarily Evacuate Ahead Of Irma","outlet":"CBS Miami","url":"https://www.cbsnews.com/miami/news/miami-beach-evacuations-hurricane-irma","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"back-bay-floodwall","title":"Army Corps Back Bay storm wall","area":"citywide","scope":"citywide","category":"flooding","years":"2020-2023","summary":"The Army Corps' 2020 draft plan for Miami-Dade included floodwalls up to 20 ft along Biscayne Bay. It was resoundingly rejected; the county pushed for nature-based alternatives and the Corps agreed to restudy.","facts":["Floodwall up to 20 ft tall along Biscayne Bay in the 2020 draft"],"sides":[{"who":"Army Corps","position":"Floodwalls, surge barriers and pumps plus elevating homes"},{"who":"Residents and county","position":"Walls would block access and views; prefer nature-based protection"},{"who":"Environmental groups","position":"Support oyster reefs and other natural defenses"}],"tensions":["nature-vs-grey"],"concerns":["flooding","beach-access","habitat"],"card_ideas":["living-shoreline","green-grey-hybrid","public-access-guarantee"],"sources":[{"title":"Closing off Biscayne Bay with massive gates? New ideas to protect Miami from storms","outlet":"WLRN","url":"https://www.wlrn.org/environment/2023-02-20/closing-off-biscayne-bay-with-massive-gates-new-ideas-to-protect-miami-from-storm","kind":"news"},{"title":"Army Corps of Engineers Scraps Biscayne Bay Floodwall","outlet":"Commercial Observer","url":"https://commercialobserver.com/2022/09/army-corp-of-engineers-scraps-biscayne-bay-floodwall/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"pump-bacteria","title":"Flood pumps discharge fecal bacteria into the bay","area":"west-avenue","scope":"area","category":"water-quality","years":"2016-2021","summary":"Sampling after the 2014 and 2015 king tides found pumped floodwater with high levels of fecal indicator bacteria entering Biscayne Bay. The city called the sampling a snapshot and pointed to sewer upgrades.","facts":["In one case bacteria levels were more than 600 times the state limit (CBS Miami citing the Miami Herald)"],"sides":[{"who":"NOAA and FIU researchers","position":"Discharges need monitoring and possibly treatment"},{"who":"City officials","position":"Sampling was a snapshot; sewage pipes are being replaced"}],"tensions":["infrastructure-side-effects"],"concerns":["water-quality","habitat"],"card_ideas":["environmental-challenge","water-quality-monitoring","drainage-upgrade"],"sources":[{"title":"Study: Miami Beach King Tides Flush Human Waste Into Biscayne Bay","outlet":"CBS Miami","url":"https://cbsnews.com/miami/news/study-miami-beach-king-tides-flush-human-waste-into-biscayne-bay","kind":"news"},{"title":"Dirty water: unintended consequence of climate resiliency","outlet":"Eos","url":"https://eos.org/articles/dirty-water-unintended-consequence-of-climate-resiliency","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"fish-kill-2020","title":"August 2020 Biscayne Bay fish kill","area":"west-avenue","scope":"area","category":"water-quality","years":"2020","summary":"Thousands of dead fish surfaced from North Miami to Virginia Key in August 2020. Researchers tied the low oxygen to nutrient pollution from septic, sewage leaks, stormwater and fertilizer.","facts":["At least 27,640 fish estimated dead from 497 public photos","A consensus statement was signed by 43 research groups and agencies"],"sides":[{"who":"Miami Waterkeeper","position":"Largest recorded fish kill in the bay; nutrient pollution must be cut"},{"who":"FWC scientists","position":"Heavy rain and unusually hot water helped trigger it"}],"tensions":["infrastructure-side-effects"],"concerns":["water-quality","habitat"],"card_ideas":["environmental-challenge","water-quality-monitoring","living-shoreline"],"sources":[{"title":"Fish Kill in Biscayne Bay: A Report and a Plan","outlet":"Miami Waterkeeper","url":"https://storymaps.arcgis.com/stories/b5d43852c8984a4c8db4d077ec04bd35","kind":"advocacy"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"sewer-breaks-2020","title":"Sewer main breaks spill into Biscayne Bay","area":"citywide","scope":"citywide","category":"water-quality","years":"2019-2020","summary":"In March 2020 sewer line breaks released about 1.4 million gallons of raw sewage into Biscayne Bay. The Florida DEP sued the city and two contractors over breaks that discharged nearly 1.7 million gallons.","facts":["About 1.4 million gallons spilled in March 2020","Nearly 1.7 million gallons across breaks from July 2019 to March 2020"],"sides":[{"who":"Florida DEP","position":"Sued the city and contractors"},{"who":"City","position":"Asked residents to cut water use; brought pumper trucks"}],"tensions":["infrastructure-side-effects","costs-on-owners"],"concerns":["water-quality","cost"],"card_ideas":["emergency-funding","water-quality-monitoring"],"sources":[{"title":"Miami Beach lost half its sewage capacity. Age was partly to blame","outlet":"WLRN","url":"https://www.wlrn.org/environment/2020-03-10/miami-beach-lost-half-its-sewage-capacity-age-was-partly-to-blame","kind":"news"},{"title":"Sewer Line Breaks Prompt Swimming and Water Use Warnings","outlet":"WUSF","url":"https://health.wusf.usf.edu/health-news-florida/2020-03-05/sewer-line-breaks-prompt-swimming-and-water-use-warnings-for-miami-beach-surfside-and-bal-harbour","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"sargassum-2023","title":"Record sargassum bloom","area":"collins-mid-beach","scope":"area","category":"environment","years":"2023","summary":"A record sargassum bloom hit South Florida in 2023. Miami-Dade's cleanup spending kept rising, with Miami Beach between 26th and 31st streets and the South Pointe jetty among the hotspots.","facts":["County cleanup rose from $2.8 million (2020) to $3.9 million, with about $6 million sought for 2023"],"sides":[{"who":"Scientists","position":"Fertilizer runoff, sewage and warmer water feed the bloom"},{"who":"Miami-Dade County","position":"Landfill disposal is not ideal; needs more state money"}],"tensions":["tourism-vs-residents","budget-tradeoff"],"concerns":["beach-access","cost","water-quality"],"card_ideas":["tourism-campaign","emergency-funding","public-campaign"],"sources":[{"title":"Seaweed mass expands, reaches record tonnage","outlet":"WLRN","url":"https://www.wlrn.org/environment/2023-04-04/seaweed-mass-expands-reaches-record-tonnage-messy-florida-beaches-inevitable","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"turtle-lighting-2024","title":"Sea turtle lighting ordinance","area":"citywide","scope":"citywide","category":"environment","years":"2024","summary":"Miami Beach strengthened its turtle nesting lighting rules in 2024 to cover lights visible from the beach and interior hotel lighting, and limited fireworks to barges.","facts":["Approved on second reading October 30, 2024","Nesting season starts April 1 in Miami Beach"],"sides":[{"who":"City","position":"Protect nesting turtles from artificial light"},{"who":"Oceanfront hotels and condos","position":"New rules reach interior lighting and window treatments"}],"tensions":["tourism-vs-residents"],"concerns":["habitat","business-impact"],"card_ideas":["environmental-challenge","tourism-campaign"],"sources":[{"title":"Miami Beach Strengthens Sea Turtle-Friendly Lighting Ordinance","outlet":"City of Miami Beach","url":"https://miamibeachfl.gov/?p=346038","kind":"official"},{"title":"Miami Beach sea turtle ordinance on lights","outlet":"WLRN","url":"https://www.wlrn.org/environment/2024-09-04/miami-beach-sea-turtle-ordinance-lights","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"brittany-bay-living-shoreline","title":"Brittany Bay Park living shoreline","area":"collins-mid-beach","scope":"area","category":"environment","years":"2021-2023","summary":"Miami Beach and The Nature Conservancy built a hybrid green-gray living shoreline at Brittany Bay Park on Indian Creek. The cost grew from the groundbreaking estimate.","facts":["$2.8 million completed cost versus a $1.8 million groundbreaking estimate"],"sides":[{"who":"City and The Nature Conservancy","position":"Hybrid green-gray resilience"}],"tensions":["nature-vs-grey"],"concerns":["habitat","flooding","cost"],"card_ideas":["living-shoreline","green-grey-hybrid"],"sources":[{"title":"Miami Beach Set to Take Wraps Off Brittany Bay Park Living Shoreline","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/?p=260338","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"indian-creek-park-shoreline","title":"Indian Creek Park living shoreline","area":"collins-mid-beach","scope":"area","category":"environment","years":"2020s","summary":"Indian Creek Park pairs a waterside promenade with a living shoreline of mangroves between the old seawall and a new seawall four feet higher.","facts":["New seawall four feet higher than the existing one"],"sides":[{"who":"Designers (S&ME)","position":"Tidal flushing and mangroves create habitat while raising the edge"}],"tensions":["nature-vs-grey"],"concerns":["habitat","flooding","beach-access"],"card_ideas":["living-shoreline","green-grey-hybrid"],"sources":[{"title":"Indian Creek Park Living Shoreline","outlet":"S&ME","url":"https://smeinc.com/?p=8344","kind":"industry"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"beach-renourishment","title":"Army Corps beach renourishment","area":"collins-mid-beach","scope":"area","category":"environment","years":"2021-2025","summary":"The Army Corps placed sand along eroded Miami Beach segments under a $40.4 million contract, and the federal project was reauthorized for 50 years from 2025.","facts":["$40.4 million contract (July 2021)","About 835,000 cubic yards of sand along about 11,400 ft of shoreline"],"sides":[{"who":"Army Corps and county","position":"Renourish eroded segments; consider breakwaters and groins"}],"tensions":["nature-vs-grey","tourism-vs-residents"],"concerns":["beach-access","flooding","habitat"],"card_ideas":["living-shoreline","tourism-campaign"],"sources":[{"title":"USACE nearing completion of the Miami Beach project","outlet":"Dredging Today","url":"https://dredgingtoday.com/?p=82517","kind":"industry"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"palms-to-shade-trees","title":"Palms swapped for shade trees","area":"collins-mid-beach","scope":"area","category":"environment","years":"2021-2022","summary":"Miami Beach adopted an urban forestry plan to cut palms from about 60% of the canopy to 25% over 30 years, drawing pushback over the city's image, including a downsized plan for 41st Street.","facts":["Palms nearly 60% of the canopy; target 25%"],"sides":[{"who":"Then-Vice Mayor Steven Meiner","position":"Palm reductions could hurt the city's cultural, historical and economic brand"},{"who":"Environmental advocates","position":"Shade trees absorb more CO2 and stormwater"}],"tensions":["tourism-vs-residents"],"concerns":["habitat","heat","city-identity"],"card_ideas":["public-campaign","tourism-campaign"],"sources":[{"title":"Miami Beach climate change plan would see iconic palm trees swapped out","outlet":"CBS Miami","url":"https://www.cbsnews.com/amp/miami/news/miami-beach-climate-change-plan-iconic-palm-trees-swapped-canopy-trees","kind":"news"},{"title":"Florida cities and palm trees","outlet":"NPR","url":"https://www.npr.org/2022/01/05/1064876188/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"north-beach-oceanside-park","title":"North Beach Oceanside Park upgrade","area":"north-beach-oceanside","scope":"area","category":"environment","years":"2023","summary":"The city completed a $15.8 million upgrade of North Beach Oceanside Park and the adjoining Beachwalk, with expanded paths and new landscaping.","facts":["$15.8 million project","Net increase of 188 trees"],"sides":[{"who":"City","position":"More shade, paths and park amenities by the beach"}],"tensions":["public-benefit-swap"],"concerns":["beach-access","habitat"],"card_ideas":["public-access-guarantee","living-shoreline"],"sources":[{"title":"Miami Beach Completes $15.8 Million Upgrade to North Beach Oceanside Park","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/wp-content/uploads/2023/10/Miami-Beach-Completes-15.8-Million-Upgrade-to-North-Beach-Oceanside-Park.pdf","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"dune-management","title":"Coastal Dune Management Plan","area":"citywide","scope":"citywide","category":"environment","years":"2015","summary":"The city's Coastal Dune Management Plan aims to use the best available science to enhance the dunes' environmental and storm protection functions.","facts":["Includes a $300,000 citywide dune restoration project"],"sides":[{"who":"City","position":"Dunes are storm protection and habitat"}],"tensions":["nature-vs-grey"],"concerns":["habitat","flooding","beach-access"],"card_ideas":["living-shoreline","environmental-challenge"],"sources":[{"title":"Miami Beach Coastal Dune Management Plan (presentation)","outlet":"FSBPA","url":"https://www.fsbpa.com/2015TechPresentations/Wells.pdf","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"fontainebleau-water-park","title":"Fontainebleau water park","area":"collins-mid-beach","scope":"area","category":"development","years":"2025-2026","summary":"The Fontainebleau at 4441 Collins Ave proposed up to 11 water slides, one about 120 ft tall, needing 11 variances from the Historic Preservation Board. A state bill was amended to let it bypass board review, and the city moved toward suing the state. As of March 2026 no final board decision had been reported, so the outcome is unresolved.","facts":["Up to 11 slides, one about 120 ft tall","Nearly three dozen speakers opposed it at the November 2025 hearing, one spoke in favor","City Commission voted 4-1 to authorize the mayor to sue the state"],"sides":[{"who":"Mayor Steven Meiner","position":"Tallahassee is not the zoning board of Miami Beach","quote":"Tallahassee is not the zoning board of Miami Beach."},{"who":"Miami Design Preservation League","position":"A slide tower would be a visually dominant structure on the landmark"},{"who":"Fontainebleau","position":"No added traffic or density; not open to the public"}],"tensions":["growth-vs-heritage","local-vs-state"],"concerns":["height","historic-character","local-control"],"card_ideas":["hotel-development","tourism-campaign","environmental-challenge","preservation-appeal"],"sources":[{"title":"Miami Beach leaders protest state bill as Fontainebleau water park proposal draws scrutiny","outlet":"WLRN","url":"https://www.wlrn.org/development/2026-03-10/miami-beach-fontainebleau-water-park-bill-399","kind":"news"},{"title":"Our Positions at the February 10, 2026 Historic Preservation Board","outlet":"Miami Design Preservation League","url":"https://mdpl.org/news/2026/02/our-positions-at-the-february-10-2026-historic-preservation-board","kind":"advocacy"},{"title":"Fontainebleau Miami Beach water park plan could drown","outlet":"The Real Deal","url":"https://therealdeal.com/miami/2025/11/21/fontainebleau-miami-beach-water-park-plan-could-drown/","kind":"news"}],"verification":{"status":"resolved","notes":["Final board decision and case file number not found"],"resolution":"Framed as unresolved; no final decision is claimed."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"ocean-terrace-upzoning","title":"Ocean Terrace upzoning rejected","area":"north-beach-oceanside","scope":"area","category":"development","years":"2022-2023","summary":"Voters were asked to upzone the historic Ocean Terrace blocks between 73rd and 75th streets from 75 ft to 250 ft. Voters rejected the plan in November 2022, and the developer returned with a plan keeping historic facades but still including a tower.","facts":["Height limit would have risen from 75 ft (8 stories) to 250 ft (22 stories)","Developer spent more than $700,000 campaigning"],"sides":[{"who":"Developer Sandor Scher","position":"Upzoning would revitalize North Beach"},{"who":"Opponents","position":"Would destroy historic architecture and the low-rise feel"}],"tensions":["growth-vs-heritage"],"concerns":["height","historic-character","density"],"card_ideas":["hotel-development","neighborhood-petition","referendum-demand","public-campaign"],"sources":[{"title":"Ocean Terrace's future unclear after voters reject plan for 22-story condo tower","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/news/ocean-terraces-future-unclear-after-voters-reject-plan-for-22-story-condo-tower-8029149/","kind":"news"},{"title":"North Beach developer plans new luxury condo tower after losing at ballot box","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/uncategorized/north-beach-developer-plans-new-luxury-condo-tower-after-losing-at-ballot-box-8433915/","kind":"news"},{"title":"Certification of Official Results, November 8, 2022","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/wp-content/uploads/2022/11/Certification-of-Official-Results-Bates.pdf","kind":"official"}],"verification":{"status":"resolved","notes":["Vote share comes from one secondary source; confirm against certified results"],"resolution":"Dropped the single-source vote percentage; linked the city's certified results for the outcome."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"north-beach-resort-overlay","title":"North Beach Oceanside Resort Overlay ballot","area":"north-beach-oceanside","scope":"area","category":"development","years":"2022","summary":"A November 2022 ballot question asked voters to raise the floor area ratio on oceanfront lots at 6605-6757 Collins Avenue, because the City Charter requires a vote for FAR increases.","facts":["FAR from 2.25 to 3.0, with incentives up to 4.5 for qualifying hotels","Lots at 6605-6757 Collins Avenue"],"sides":[{"who":"City Charter","position":"FAR increases need voter approval"},{"who":"Hotel developers","position":"More density brings hotel investment"}],"tensions":["public-benefit-swap","growth-vs-heritage"],"concerns":["density","economy","local-control"],"card_ideas":["hotel-development","referendum-demand","tourism-campaign"],"sources":[{"title":"November 8, 2022 Ballot Questions","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/2022election-info/","kind":"official"},{"title":"Certification of Official Results","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/wp-content/uploads/2022/11/Certification-of-Official-Results-Bates.pdf","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"deauville-demolition","title":"Deauville hotel demolished","area":"north-beach-oceanside","scope":"area","category":"heritage","years":"2022","summary":"The Deauville was ordered demolished as unsafe in 2022. Preservationists called it demolition by neglect and appealed; the county appeals board upheld the order, and the hotel was imploded days after voters rejected a redevelopment measure.","facts":["Miami-Dade Board of Rules and Appeals voted 9-0 to uphold demolition","About 4-acre oceanfront site"],"sides":[{"who":"Miami Beach deputy city manager","position":"Demolition by neglect, absolutely"},{"who":"Miami Design Preservation League","position":"The city did not follow its historic preservation laws"},{"who":"North Beach residents","position":"The Deauville was a cultural gem"}],"tensions":["growth-vs-heritage"],"concerns":["historic-character","property-neglect"],"card_ideas":["preservation-appeal","hotel-development","referendum-demand"],"sources":[{"title":"After Deauville implosion, property's future remains uncertain","outlet":"WLRN","url":"https://www.wlrn.org/local-news/2022-11-14/after-deauville-implosion-propertys-future-remains-uncertain","kind":"news"},{"title":"Miami Beach's fabled Deauville Beach Resort imploded","outlet":"The Architect's Newspaper","url":"https://www.archpaper.com/2022/11/miami-beach-fabled-deauville-beach-resort-imploded-future-redevelopment-plans-unsettled/?amp=1","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"clevelander-live-local","title":"Clevelander tower under the Live Local Act","area":"new-area","scope":"new-area","category":"development","years":"2023-2024","summary":"The Clevelander's owner proposed a 30-story tower on Ocean Drive under Florida's Live Local Act, then filed an 18-story plan with affordable units after an outcry. Ocean Drive heights are otherwise limited to 50 ft.","facts":["Revised to 18 stories with 137 units, 55 affordable","Ocean Drive height limit of 50 ft"],"sides":[{"who":"Then-Mayor Dan Gelber","position":"A tragic idea"},{"who":"Developer Jesta Group","position":"Workforce housing under state law"}],"tensions":["growth-vs-heritage","local-vs-state"],"concerns":["height","affordability","historic-character"],"card_ideas":["hotel-development","live-local-bypass","preservation-appeal"],"sources":[{"title":"Tragic idea, Miami Beach Mayor on plans to turn iconic Clevelander Hotel into high-rise","outlet":"CBS Miami","url":"https://www.cbsnews.com/amp/miami/news/plans-to-turn-clevelander-into-high-rise-upsetting-many/","kind":"news"}],"verification":{"status":"conflict","notes":["No status found after 2024"]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"live-local-workforce-housing","title":"Live Local Act and workforce housing","area":"citywide","scope":"citywide","category":"housing","years":"2023-2025","summary":"Florida's Live Local Act lets developers bypass local zoning if at least 40% of units are workforce or affordable housing. Miami Beach wants workers living locally without losing its character, and a report found the law still misses many public-sector workers.","facts":["At least 40% of units at 80% to 120% of area median income"],"sides":[{"who":"Commissioner Alex Fernandez","position":"Large towers along Alton Road would hurt tourism and workers' quality of life"},{"who":"Florida Policy Institute","position":"Not enough affordable housing for sole-earner firefighters, teachers and police"}],"tensions":["local-vs-state"],"concerns":["affordability","height","local-control"],"card_ideas":["live-local-bypass","neighborhood-petition"],"sources":[{"title":"Miami Beach Wants Workers Living Local Without Giving In To Live Local Act","outlet":"Bisnow","url":"https://www.bisnow.com/news/south-florida/construction-development/miami-beach-wants-to-keep-workforce-local-without-losing-character-130953","kind":"news"},{"title":"Report reveals Florida's workforce housing is unaffordable for many public sector workers","outlet":"WLRN","url":"https://www.wlrn.org/government-politics/2024-11-15/report-reveals-floridas-workforce-housing-is-unaffordable-for-many-public-sector-workers","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"ritz-carlton-tower","title":"Ritz-Carlton South Beach condo addition","area":"new-area","scope":"new-area","category":"development","years":"2023","summary":"The Historic Preservation Board approved a 15-story condo addition at the Ritz-Carlton South Beach despite objections that the tower was out of character and would shade the beach.","facts":["15-story, 182-foot tower"],"sides":[{"who":"Critics","position":"Out of character and would shadow the beach"},{"who":"Owners","position":"Won approval for the addition"}],"tensions":["growth-vs-heritage"],"concerns":["height","beach-access","historic-character"],"card_ideas":["hotel-development","preservation-appeal"],"sources":[{"title":"Owners of South Beach's Ritz-Carlton Win Approval to Add 15-Story Condo","outlet":"Commercial Observer","url":"https://commercialobserver.com/2023/10/ritz-carlton-south-beach-lincoldn-road/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"five-hundred-alton","title":"500-700 Alton tower and Park on Fifth","area":"south-pointe","scope":"area","category":"development","years":"2018-2019","summary":"The city approved a tall tower at the South Beach gateway at 500-700 Alton Road in exchange for a developer-donated 3-acre public park, with a pedestrian bridge funded by the 2018 GO Bond.","facts":["Tower over 500 ft (sources give 519 ft and 553 ft)","3-acre park donated to the city","$10 million GO Bond for the bridge"],"sides":[{"who":"City Commission","position":"Height traded for a public park"},{"who":"Developer Russell Galbut","position":"Builds and donates the park"}],"tensions":["public-benefit-swap"],"concerns":["height","parks","density"],"card_ideas":["public-benefit-swap","hotel-development","public-access-guarantee"],"sources":[{"title":"Beach commission to hear 44-story limit on Alton Road site","outlet":"Miami Today","url":"https://www.miamitodaynews.com/breaking/beach-commission-hear-44-story-limit-alton-road-site/","kind":"news"},{"title":"Crescent Heights reveals new renderings of Park on Fifth","outlet":"Profile Miami","url":"https://profilemiamire.com/miamirealestate/2019/12/12/crescent-heights-reveals-new-renderings-of-park-coming-to-500-alton-in-south-beach","kind":"news"}],"verification":{"status":"resolved","notes":["Sources disagree on tower height (519 ft vs 553 ft)"],"resolution":"Height stated as over 500 ft with both reported figures named."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"convention-center-hotel","title":"Convention Center hotel referendums","area":"new-area","scope":"new-area","category":"development","years":"2016-2018","summary":"A 2016 convention center hotel plan failed at the ballot over size and traffic. A smaller 800-room plan passed in 2018, clearing the 60 percent required.","facts":["2016 plan got 54 percent","2018 plan got about 64 percent; 60 percent needed","800 rooms, 185 ft"],"sides":[{"who":"Developers","position":"Hotel supports the convention center"},{"who":"2016 opponents","position":"Too big, too much traffic"}],"tensions":["public-benefit-swap","tourism-vs-residents"],"concerns":["height","traffic","economy"],"card_ideas":["hotel-development","referendum-demand","tourism-campaign"],"sources":[{"title":"Voters approve Miami Beach convention center hotel","outlet":"Terra Group (reprint)","url":"https://terragroup.com/voters-approve-miami-beach-convention-center-hotel","kind":"industry"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"art-deco-district-1979","title":"Art Deco District listed (1979)","area":"citywide","scope":"citywide","category":"heritage","years":"1976-1979","summary":"Barbara Baer Capitman and the Miami Design Preservation League campaigned with vigils and protests to list the Art Deco District on the National Register in 1979, though some buildings were still lost.","facts":["Listed May 14, 1979","First 20th-century district on the National Register"],"sides":[{"who":"Barbara Baer Capitman","position":"Stood in front of bulldozers to save the district"},{"who":"Developers of the era","position":"Demolished the Senator and New Yorker hotels"}],"tensions":["growth-vs-heritage"],"concerns":["historic-character"],"card_ideas":["preservation-appeal","public-campaign"],"sources":[{"title":"Barbara Baer Capitman: South Beach's Art Deco Hero","outlet":"National Trust (Saving Places)","url":"https://savingplaces.org/stories/barbara-baer-capitman-south-beach-art-deco-hero","kind":"advocacy"},{"title":"Miami Beach Deco","outlet":"PBS American Experience","url":"https://www.pbs.org/wgbh/americanexperience/features/miami-beach-deco/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"alton-bayfront-overlay","title":"Alton Beach Bayfront Overlay density","area":"west-avenue","scope":"area","category":"development","years":"2025","summary":"A June 2025 commission meeting reportedly considered a higher-density residential category on the Alton bayfront tied to public benefits.","facts":["Density tied to public benefits"],"sides":[{"who":"Commission","position":"Density for public benefits"},{"who":"Concerned voices","position":"State law could affect voter control over FAR"}],"tensions":["public-benefit-swap","local-vs-state"],"concerns":["density","local-control"],"card_ideas":["public-benefit-swap","referendum-demand"],"sources":[{"title":"Miami Beach Commission votes on two major development items amid legal concerns","outlet":"Soar (AI summary)","url":"https://cp.soar.com/articles/5096489/Miami-Beach/Miami-Dade-County/Florida/Miami-Beach-Commission-votes-on-two-major-development-items-amid-legal-concerns","kind":"other"}],"verification":{"status":"conflict","notes":["Only source is an AI-generated summary; verify against commission minutes or drop"]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"ocean-drive-traffic","title":"Ocean Drive closed to cars, then reopened","area":"new-area","scope":"new-area","category":"mobility","years":"2020-2025","summary":"Ocean Drive closed to cars in 2020, partly reopened in 2022 with a bike lane, and after a Clevelander lawsuit a judge ordered two-way traffic restored; the bike lanes came out in 2025.","facts":["Closed to cars in May 2020","Reopened to two-way traffic in February 2025"],"sides":[{"who":"Clevelander and hotel owners","position":"The pedestrian plaza hurt business and safety"},{"who":"Bike and pedestrian advocates","position":"Removing bike lanes is a setback"},{"who":"Mayor","position":"Called the judge's decision outrageous"}],"tensions":["tourism-vs-residents"],"concerns":["traffic","safety","business-impact"],"card_ideas":["public-access-guarantee","tourism-campaign","neighborhood-petition"],"sources":[{"title":"Miami Beach reopens Ocean Drive to two-way vehicle traffic, removing bike lanes","outlet":"WLRN","url":"https://www.wlrn.org/news-in-brief/2025-02-07/miami-beach-reopens-ocean-drive-to-two-way-vehicle-traffic-removing-bike-lanes","kind":"news"},{"title":"Ocean Drive reopens to two-way traffic after Clevelander lawsuit","outlet":"NBC Miami","url":"https://www.nbcmiami.com/news/local/ocean-drive-reopens-to-2-way-traffic-removes-bike-lanes-after-clevelander-lawsuit/3538279/?amp=1","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"spring-break-curfew-2024","title":"Spring break curfew","area":"south-pointe","scope":"area","category":"quality-of-life","years":"2023-2024","summary":"After two fatal shootings in 2023, Miami Beach set a weekend curfew south of 23rd Street in March 2024, limited beach access and closed liquor stores early under its Break Up with Spring Break campaign.","facts":["Curfew from 11:59 p.m. Friday to 6 a.m. Monday south of 23rd Street"],"sides":[{"who":"City","position":"Protecting public safety"},{"who":"Commissioner Ricky Arriola","position":"Panic-stricken politicians reacting rather than planning"},{"who":"Business owners","position":"A lockdown means no business"}],"tensions":["tourism-vs-residents"],"concerns":["safety","business-impact","beach-access"],"card_ideas":["tourism-campaign","neighborhood-petition","public-access-guarantee"],"sources":[{"title":"Miami Beach enacts emergency curfew amid spring break crackdown","outlet":"Local10","url":"https://local10.com/news/local/2024/03/15/miami-beach-enacts-emergency-curfew-amid-spring-break-crackdown","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"short-term-rental-ban","title":"Short-term rental ban and fines","area":"citywide","scope":"citywide","category":"housing","years":"2016-2020","summary":"Short-term rentals are illegal in most Miami Beach neighborhoods. Fines starting at $20,000 were struck down, then restructured; the city collected only a fraction of what it levied.","facts":["Fines of $20,000 up to $100,000 from 2016","About $8 million in fines issued, about $500,000 collected"],"sides":[{"who":"City","position":"Rentals hurt quality of life in neighborhoods"},{"who":"Home-sharing companies","position":"Rentals support the local economy"}],"tensions":["tourism-vs-residents"],"concerns":["affordability","quality-of-life","economy"],"card_ideas":["neighborhood-petition","tourism-campaign"],"sources":[{"title":"Part of Miami Beach short-term rental law still valid, court rules","outlet":"Avalara","url":"https://www.avalara.com/mylodgetax/en/blog/2020/10/part-of-miami-beach-short-term-rental-law-still-valid-court-rules-in-reversal.html","kind":"industry"},{"title":"Miami Beach has collected only 2 percent of short-term rental fines","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/news/miami-beach-has-collected-just-two-percent-of-5-million-in-short-term-rental-fines-9242368/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"surfside-aftermath","title":"After Surfside: unsafe buildings and recertification costs","area":"citywide","scope":"citywide","category":"housing","years":"2021-2024","summary":"After the 2021 Surfside collapse, dozens of South Florida buildings were vacated as unsafe, many in Miami Beach, and Florida's recertification law raised costs and special assessments for condo owners.","facts":["At least 26 buildings vacated, 18 in Miami Beach","Recertification at 25 years within 3 miles of the coast, then every 10 years"],"sides":[{"who":"Condo owners","position":"Special assessments force some to pay up or move out"},{"who":"State","position":"Recertification keeps buildings safe"}],"tensions":["costs-on-owners"],"concerns":["safety","affordability","cost"],"card_ideas":["elevate-buildings","emergency-funding"],"sources":[{"title":"At least 26 buildings deemed unsafe, evacuated since Surfside","outlet":"NBC Miami","url":"https://www.nbcmiami.com/news/local/surfside-condo-collapse/at-least-26-buildings-in-south-florida-deemed-unsafe-evacuated-since-surfside-condo-collapse/3059035/?amp=1","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"go-bond-2018","title":"2018 General Obligation Bond","area":"citywide","scope":"citywide","category":"budget","years":"2018-2026","summary":"Voters approved a $439 million GO Bond in 2018 for 57 projects across parks, neighborhoods and infrastructure, and public safety, issued in tranches over a decade.","facts":["$439 million for 57 projects","$169M parks and culture, $198M neighborhoods and infrastructure, $72M public safety","Each measure passed with about 70 percent"],"sides":[{"who":"Voters","position":"Approved all three measures"}],"tensions":["budget-tradeoff","public-benefit-swap"],"concerns":["cost","parks","flooding"],"card_ideas":["emergency-funding","public-campaign"],"sources":[{"title":"GO Bond Program","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/de/egovapp/city-hall/gobonddepartment/","kind":"official"},{"title":"Miami Beach G.O. Bond coverage","outlet":"Miami Today","url":"https://www.miamitodaynews.com/?p=57734","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"72nd-street-complex","title":"72nd Street community complex","area":"north-beach-oceanside","scope":"area","category":"budget","years":"2018-2026","summary":"North Beach's GO Bond complex (park, library, pools, garage) grew in cost and drew resident objections to a rooftop Olympic pool and to moving the library, which needs a referendum.","facts":["$53.8 million GO Bond, about $107 million all-in","50-meter pool on top of a 500-space garage"],"sides":[{"who":"Resident-hired engineers","position":"A rooftop Olympic pool has never been done and is a weight hazard"},{"who":"Residents","position":"Library land cannot be sold without a referendum"}],"tensions":["budget-tradeoff","public-benefit-swap"],"concerns":["cost","parks","safety"],"card_ideas":["referendum-demand","neighborhood-petition","emergency-funding"],"sources":[{"title":"72 Street Community Complex","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/projects/72-street-community-complex/","kind":"official"},{"title":"Miami Beach Planning $107M Project With Olympic Pool Atop Parking Garage","outlet":"Bisnow","url":"https://www.bisnow.com/news/south-florida/architecture-design/miami-beach-olympic-pool-parking-garage-110238","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"}]$$)) ) f) s
   ON t.ID = s.v:id::STRING
   WHEN MATCHED THEN UPDATE SET
     TITLE = s.v:title::STRING, AREA = s.v:area::STRING, SCOPE = s.v:scope::STRING, CATEGORY = s.v:category::STRING,
     YEARS = s.v:years::STRING, SUMMARY = s.v:summary::STRING, FACTS = s.v:facts, SIDES = s.v:sides,
     TENSIONS = s.v:tensions::ARRAY, CONCERNS = s.v:concerns::ARRAY, CARD_IDEAS = s.v:card_ideas::ARRAY,
     VERIFICATION = s.v:verification, RETRIEVED_AT = s.v:retrieved_at::DATE, LOADED_AT = CURRENT_TIMESTAMP()
   WHEN NOT MATCHED THEN INSERT (ID, TITLE, AREA, SCOPE, CATEGORY, YEARS, SUMMARY, FACTS, SIDES, TENSIONS, CONCERNS, CARD_IDEAS, VERIFICATION, REVIEW_STATUS, RETRIEVED_AT, LOADED_AT)
   VALUES (s.v:id::STRING, s.v:title::STRING, s.v:area::STRING, s.v:scope::STRING, s.v:category::STRING, s.v:years::STRING,
     s.v:summary::STRING, s.v:facts, s.v:sides, s.v:tensions::ARRAY, s.v:concerns::ARRAY, s.v:card_ideas::ARRAY,
     s.v:verification, s.v:review_status::STRING, s.v:retrieved_at::DATE, CURRENT_TIMESTAMP());

