INSERT INTO COASTAL_CLASH.CORPUS.SOURCES (ISSUE_ID, TITLE, OUTLET, URL, KIND)
   SELECT i.value:id::STRING, s.value:title::STRING, s.value:outlet::STRING, s.value:url::STRING, s.value:kind::STRING
   FROM TABLE(FLATTEN(INPUT => PARSE_JSON($$[{"id":"west-ave-road-raising","title":"West Avenue road raising and stormwater","area":"west-avenue","scope":"area","category":"flooding","years":"2018-2025","summary":"The city is raising West Avenue streets by up to about two feet with new drainage, pumps, water and sewer lines. Most residents refused liability-release harmonization agreements, and nearby businesses objected to lost parking and construction disruption.","facts":["Streets raised by as much as two feet","Total budget about $100 million to $105 million (the city's English and French project pages list different figures)","Construction on a block began in June 2025 (NBC6)"],"sides":[{"who":"City of Miami Beach","position":"Raising roads and adding drainage protects against king tide and storm flooding"},{"who":"Residents","position":"Raised roads may push water onto private property; most refused harmonization agreements"},{"who":"Businesses","position":"Lost parking and construction hurt daily business"}],"tensions":["raise-the-street-vs-homes-below","infrastructure-side-effects"],"concerns":["flooding","construction-disruption","parking","liability"],"card_ideas":["drainage-upgrade","elevate-buildings","neighborhood-petition","harmonization-deal"],"sources":[{"title":"West Avenue Neighborhood Enhancements","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/projects/west-avenue-neighborhood-improvements-project-phase-ii/","kind":"official"},{"title":"Miami Beach wants higher roads and pumps to fight sea rise. Some residents say no way","outlet":"WLRN","url":"https://www.wlrn.org/environment/2018-05-17/miami-beach-wants-higher-roads-and-pumps-to-fight-sea-rise-some-residents-say-no-way","kind":"news"},{"title":"Controversy arising in Miami Beach over raising roads to combat flooding","outlet":"Local10","url":"https://local10.com/news/local/2022/02/21/controversy-arising-in-miami-beach-over-raising-roads-to-combat-flooding","kind":"news"},{"title":"Miami Beach resiliency project brings flood protection and frustration","outlet":"NBC6","url":"https://www.nbcmiami.com/investigations/miami-beach-resiliency-project-brings-flood-protection-and-frustration-for-lincoln-road-business/3756786/?amp=1","kind":"news"}],"verification":{"status":"resolved","notes":["Budget differs between the English ($105,140,819) and French ($100,229,771) versions of the city project page"],"resolution":"Stated as a range and named the discrepancy instead of picking one figure."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"first-street-stormwater","title":"First Street and South Pointe stormwater project","area":"south-pointe","scope":"area","category":"flooding","years":"2020-2026","summary":"First Street between Alton Road and Washington Avenue will be rebuilt and raised to at least 3.7 ft NAVD with a new pump station at First Street and Washington Avenue. The community rejected an earlier pump site; raising Alton Road and South Pointe Drive was deferred for budget reasons.","facts":["Road raised to a minimum of 3.7 ft NAVD","Total budget $60 million","Phases 1 and 2 funded; in design as of February 2026, with construction expected to start in 2026-2027","Pump station at the southeast corner of First Street and Washington Avenue"],"sides":[{"who":"City of Miami Beach","position":"Reduce flood risk, speed recovery after storms, cut flood-related business losses"},{"who":"South of Fifth residents","position":"Rejected the pump station site at First Street and Alton Road; asked about parking, garage backflow and flood insurance"}],"tensions":["infrastructure-side-effects","budget-tradeoff"],"concerns":["flooding","infrastructure-location","parking","cost"],"card_ideas":["drainage-upgrade","emergency-funding","neighborhood-petition"],"sources":[{"title":"First Street Neighborhood Improvements & South Pointe Stormwater Project","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/projects/1-street-between-alton-road-and-washinton-avenue/","kind":"official"},{"title":"First Street Neighborhood Improvement Community Survey Results (LTC 310-2022)","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/wp-content/uploads/2022/08/LTC-310-2022-First-Street-Neighborhood-Improvement-Community-Survey-Results.pdf","kind":"official"}],"verification":{"status":"resolved","notes":["City page gives both 2026 and 2027 as the construction start"],"resolution":"Construction start stated as 2026-2027 because the city page gives both years."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"sunset-harbour-raising","title":"Sunset Harbour streets raised above shop floors","area":"west-avenue","scope":"area","category":"flooding","years":"2016-2020","summary":"Sunset Harbour streets were raised two to three feet above adjacent building floors. Some shops were left below grade and reported losing flood coverage as basements, while a consultant found nearby condos gained value.","facts":["Streets raised two to three feet above adjacent building floors","Consultant estimated an 11.9% value gain for more than 1,300 condos after the 2016 upgrade"],"sides":[{"who":"City and consultant","position":"Elevated streets and pumps raised property values"},{"who":"Business owners","position":"Buildings left below the road became uninsurable basements"}],"tensions":["raise-the-street-vs-homes-below"],"concerns":["flooding","insurance","property-value"],"card_ideas":["drainage-upgrade","elevate-buildings","harmonization-deal"],"sources":[{"title":"Miami Beach lifts roads due to sea rise, floods nearby homes","outlet":"Governing","url":"https://www.governing.com/community/miami-beach-lifts-roads-due-to-sea-rise-floods-nearby-homes","kind":"news"},{"title":"Can raising roads for sea rise make a Miami Beach home more valuable?","outlet":"National Mortgage News","url":"https://www.nationalmortgagenews.com/articles/can-raising-roads-for-sea-rise-make-a-miami-beach-home-more-valuable","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"palm-hibiscus-raising","title":"Palm and Hibiscus Islands road raising","area":"new-area","scope":"new-area","category":"flooding","years":"2018-2021","summary":"A $40.9 million road raising and drainage project on Palm and Hibiscus Islands drew an inspector general report on permit problems and cost overruns. Residents described inaccessible garages and steep driveways, and property owners sued over flooding blamed on raised roads.","facts":["$40.9 million project","Inspector general found permit problems and cost overruns"],"sides":[{"who":"Residents","position":"Roads so high garages are inaccessible and lawns flood while streets stay dry"},{"who":"Property owners (lawsuit)","position":"Raised road sent floodwater onto their property"}],"tensions":["raise-the-street-vs-homes-below","costs-on-owners"],"concerns":["flooding","cost","liability"],"card_ideas":["elevate-buildings","neighborhood-petition","harmonization-deal"],"sources":[{"title":"Miami Beach is raising roads for sea rise. Lawsuits say they're causing flooding too","outlet":"WUSF","url":"https://www.wusf.org/environment/2021-11-13/miami-beach-is-raising-roads-for-sea-rise-lawsuits-say-theyre-causing-flooding-too","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"king-tide-pumps-2014","title":"The 2014 king tide pump program","area":"citywide","scope":"citywide","category":"flooding","years":"2014-2017","summary":"Miami Beach began a pump and drainage program in 2014. South Beach stayed largely dry in the fall 2014 king tides, but critics questioned where pumps went first, and in 2017 a tropical storm overwhelmed the unfinished system.","facts":["About $500 million more planned over five years (2014)","$15 million spent on the most flood-prone areas by 2014"],"sides":[{"who":"Mayor Philip Levine","position":"Called the 2014 king tide test proof positive that the system can work"},{"who":"Political rival","position":"Questioned why early work protected areas near the mayor's buildings"},{"who":"New Times (2017)","position":"Pumps struggled to keep up with storm rainfall"}],"tensions":["infrastructure-side-effects"],"concerns":["flooding","cost","fairness"],"card_ideas":["drainage-upgrade","emergency-funding"],"sources":[{"title":"Miami uses pumps to battle flooding from sea level rise","outlet":"HPPR / NPR","url":"https://www.hppr.org/2014-10-10/miami-uses-pumps-to-battle-flooding-from-sea-level-rise","kind":"news"},{"title":"Miami Beach floods from Tropical Storm Emily overwhelm sea level rise pumps","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/riptide/2017/08/02/miami-beach-floods-from-tropical-storm-emily-overwhelm-sea-level-rise-pumps","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"stormwater-master-plan-2024","title":"2024 Stormwater Master Plan update","area":"citywide","scope":"citywide","category":"flooding","years":"2024","summary":"The City Commission adopted an update to the 2011 Stormwater Master Plan prioritizing $95 million for 20 critical resilience projects over the next decade.","facts":["$95 million for 20 projects over a decade","$103 million in stormwater projects completed since the 2011 plan"],"sides":[{"who":"City Commission","position":"Prioritize the most critical resilience projects"}],"tensions":["budget-tradeoff"],"concerns":["flooding","cost"],"card_ideas":["drainage-upgrade","emergency-funding"],"sources":[{"title":"Miami Beach Prioritizes $95 Million in Infrastructure Improvements","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/?p=295146","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"indian-creek-drive","title":"Indian Creek Drive (A1A) flood mitigation","area":"collins-mid-beach","scope":"area","category":"flooding","years":"2016-2019","summary":"Indian Creek Drive, a state road, floods at high tide. The city and FDOT partnered to raise the road and seawall, but costs rose and a seawall built too close to the water caused delays.","facts":["Roughly $25-30 million project","City paid about $5.4 million and advanced $20 million to FDOT (2016 agreement)","Tides about 2.2 ft put up to a foot of water over the seawall"],"sides":[{"who":"City and FDOT","position":"Raise the road and seawall, add a greenway barrier"},{"who":"ENR reporting","position":"Engineering failure and permitting delays pushed completion back"}],"tensions":["infrastructure-side-effects","local-vs-state"],"concerns":["flooding","cost","construction-disruption"],"card_ideas":["drainage-upgrade","green-grey-hybrid"],"sources":[{"title":"Discovery of engineering failure leads Miami Beach to flooding fix","outlet":"ENR","url":"https://enr.com/articles/42497-discovery-of-engineering-failure-leads-miami-beach-to-flooding-fix","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"seawall-ordinance-2021","title":"2021 seawall ordinance","area":"citywide","scope":"citywide","category":"flooding","years":"2021","summary":"Miami Beach adopted a seawall ordinance requiring new seawalls at a minimum elevation and giving owners up to 730 days to fix failing walls, with penalties when private seawalls flood neighbors and streets.","facts":["New seawalls at least 5.7 ft NAVD, or 4 ft if designed to rise to 5.7 ft later","Up to 730 days to bring failing seawalls into compliance"],"sides":[{"who":"City Commission","position":"Owners must maintain seawalls so they do not flood neighbors"},{"who":"Waterfront owners","position":"Costs fall on private property owners"}],"tensions":["costs-on-owners"],"concerns":["flooding","cost","liability"],"card_ideas":["elevate-buildings","emergency-funding"],"sources":[{"title":"Miami Beach Commission Adopts First Seawall Ordinance of its Kind","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/?p=149680","kind":"official"}],"verification":{"status":"conflict","notes":["Sources disagree on whether 5.7 ft NAVD applies to private or only public seawalls"]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"hurricane-irma-2017","title":"Hurricane Irma evacuation","area":"citywide","scope":"citywide","category":"flooding","years":"2017","summary":"Before Hurricane Irma, Mayor Philip Levine urged residents and tourists to evacuate the barrier island; causeways were closed and access stayed restricted after the storm.","facts":["Florida's largest evacuation, with more than 30 percent of the state's population asked to leave"],"sides":[{"who":"Mayor Philip Levine","position":"Miami Beach is a barrier island and will be seriously impacted"}],"tensions":["storm-preparedness"],"concerns":["flooding","safety"],"card_ideas":["emergency-funding","drainage-upgrade"],"sources":[{"title":"Miami Beach Mayor Asks Residents To Voluntarily Evacuate Ahead Of Irma","outlet":"CBS Miami","url":"https://www.cbsnews.com/miami/news/miami-beach-evacuations-hurricane-irma","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"back-bay-floodwall","title":"Army Corps Back Bay storm wall","area":"citywide","scope":"citywide","category":"flooding","years":"2020-2023","summary":"The Army Corps' 2020 draft plan for Miami-Dade included floodwalls up to 20 ft along Biscayne Bay. It was resoundingly rejected; the county pushed for nature-based alternatives and the Corps agreed to restudy.","facts":["Floodwall up to 20 ft tall along Biscayne Bay in the 2020 draft"],"sides":[{"who":"Army Corps","position":"Floodwalls, surge barriers and pumps plus elevating homes"},{"who":"Residents and county","position":"Walls would block access and views; prefer nature-based protection"},{"who":"Environmental groups","position":"Support oyster reefs and other natural defenses"}],"tensions":["nature-vs-grey"],"concerns":["flooding","beach-access","habitat"],"card_ideas":["living-shoreline","green-grey-hybrid","public-access-guarantee"],"sources":[{"title":"Closing off Biscayne Bay with massive gates? New ideas to protect Miami from storms","outlet":"WLRN","url":"https://www.wlrn.org/environment/2023-02-20/closing-off-biscayne-bay-with-massive-gates-new-ideas-to-protect-miami-from-storm","kind":"news"},{"title":"Army Corps of Engineers Scraps Biscayne Bay Floodwall","outlet":"Commercial Observer","url":"https://commercialobserver.com/2022/09/army-corp-of-engineers-scraps-biscayne-bay-floodwall/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"pump-bacteria","title":"Flood pumps discharge fecal bacteria into the bay","area":"west-avenue","scope":"area","category":"water-quality","years":"2016-2021","summary":"Sampling after the 2014 and 2015 king tides found pumped floodwater with high levels of fecal indicator bacteria entering Biscayne Bay. The city called the sampling a snapshot and pointed to sewer upgrades.","facts":["In one case bacteria levels were more than 600 times the state limit (CBS Miami citing the Miami Herald)"],"sides":[{"who":"NOAA and FIU researchers","position":"Discharges need monitoring and possibly treatment"},{"who":"City officials","position":"Sampling was a snapshot; sewage pipes are being replaced"}],"tensions":["infrastructure-side-effects"],"concerns":["water-quality","habitat"],"card_ideas":["environmental-challenge","water-quality-monitoring","drainage-upgrade"],"sources":[{"title":"Study: Miami Beach King Tides Flush Human Waste Into Biscayne Bay","outlet":"CBS Miami","url":"https://cbsnews.com/miami/news/study-miami-beach-king-tides-flush-human-waste-into-biscayne-bay","kind":"news"},{"title":"Dirty water: unintended consequence of climate resiliency","outlet":"Eos","url":"https://eos.org/articles/dirty-water-unintended-consequence-of-climate-resiliency","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"fish-kill-2020","title":"August 2020 Biscayne Bay fish kill","area":"west-avenue","scope":"area","category":"water-quality","years":"2020","summary":"Thousands of dead fish surfaced from North Miami to Virginia Key in August 2020. Researchers tied the low oxygen to nutrient pollution from septic, sewage leaks, stormwater and fertilizer.","facts":["At least 27,640 fish estimated dead from 497 public photos","A consensus statement was signed by 43 research groups and agencies"],"sides":[{"who":"Miami Waterkeeper","position":"Largest recorded fish kill in the bay; nutrient pollution must be cut"},{"who":"FWC scientists","position":"Heavy rain and unusually hot water helped trigger it"}],"tensions":["infrastructure-side-effects"],"concerns":["water-quality","habitat"],"card_ideas":["environmental-challenge","water-quality-monitoring","living-shoreline"],"sources":[{"title":"Fish Kill in Biscayne Bay: A Report and a Plan","outlet":"Miami Waterkeeper","url":"https://storymaps.arcgis.com/stories/b5d43852c8984a4c8db4d077ec04bd35","kind":"advocacy"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"sewer-breaks-2020","title":"Sewer main breaks spill into Biscayne Bay","area":"citywide","scope":"citywide","category":"water-quality","years":"2019-2020","summary":"In March 2020 sewer line breaks released about 1.4 million gallons of raw sewage into Biscayne Bay. The Florida DEP sued the city and two contractors over breaks that discharged nearly 1.7 million gallons.","facts":["About 1.4 million gallons spilled in March 2020","Nearly 1.7 million gallons across breaks from July 2019 to March 2020"],"sides":[{"who":"Florida DEP","position":"Sued the city and contractors"},{"who":"City","position":"Asked residents to cut water use; brought pumper trucks"}],"tensions":["infrastructure-side-effects","costs-on-owners"],"concerns":["water-quality","cost"],"card_ideas":["emergency-funding","water-quality-monitoring"],"sources":[{"title":"Miami Beach lost half its sewage capacity. Age was partly to blame","outlet":"WLRN","url":"https://www.wlrn.org/environment/2020-03-10/miami-beach-lost-half-its-sewage-capacity-age-was-partly-to-blame","kind":"news"},{"title":"Sewer Line Breaks Prompt Swimming and Water Use Warnings","outlet":"WUSF","url":"https://health.wusf.usf.edu/health-news-florida/2020-03-05/sewer-line-breaks-prompt-swimming-and-water-use-warnings-for-miami-beach-surfside-and-bal-harbour","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"sargassum-2023","title":"Record sargassum bloom","area":"collins-mid-beach","scope":"area","category":"environment","years":"2023","summary":"A record sargassum bloom hit South Florida in 2023. Miami-Dade's cleanup spending kept rising, with Miami Beach between 26th and 31st streets and the South Pointe jetty among the hotspots.","facts":["County cleanup rose from $2.8 million (2020) to $3.9 million, with about $6 million sought for 2023"],"sides":[{"who":"Scientists","position":"Fertilizer runoff, sewage and warmer water feed the bloom"},{"who":"Miami-Dade County","position":"Landfill disposal is not ideal; needs more state money"}],"tensions":["tourism-vs-residents","budget-tradeoff"],"concerns":["beach-access","cost","water-quality"],"card_ideas":["tourism-campaign","emergency-funding","public-campaign"],"sources":[{"title":"Seaweed mass expands, reaches record tonnage","outlet":"WLRN","url":"https://www.wlrn.org/environment/2023-04-04/seaweed-mass-expands-reaches-record-tonnage-messy-florida-beaches-inevitable","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"turtle-lighting-2024","title":"Sea turtle lighting ordinance","area":"citywide","scope":"citywide","category":"environment","years":"2024","summary":"Miami Beach strengthened its turtle nesting lighting rules in 2024 to cover lights visible from the beach and interior hotel lighting, and limited fireworks to barges.","facts":["Approved on second reading October 30, 2024","Nesting season starts April 1 in Miami Beach"],"sides":[{"who":"City","position":"Protect nesting turtles from artificial light"},{"who":"Oceanfront hotels and condos","position":"New rules reach interior lighting and window treatments"}],"tensions":["tourism-vs-residents"],"concerns":["habitat","business-impact"],"card_ideas":["environmental-challenge","tourism-campaign"],"sources":[{"title":"Miami Beach Strengthens Sea Turtle-Friendly Lighting Ordinance","outlet":"City of Miami Beach","url":"https://miamibeachfl.gov/?p=346038","kind":"official"},{"title":"Miami Beach sea turtle ordinance on lights","outlet":"WLRN","url":"https://www.wlrn.org/environment/2024-09-04/miami-beach-sea-turtle-ordinance-lights","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"brittany-bay-living-shoreline","title":"Brittany Bay Park living shoreline","area":"collins-mid-beach","scope":"area","category":"environment","years":"2021-2023","summary":"Miami Beach and The Nature Conservancy built a hybrid green-gray living shoreline at Brittany Bay Park on Indian Creek. The cost grew from the groundbreaking estimate.","facts":["$2.8 million completed cost versus a $1.8 million groundbreaking estimate"],"sides":[{"who":"City and The Nature Conservancy","position":"Hybrid green-gray resilience"}],"tensions":["nature-vs-grey"],"concerns":["habitat","flooding","cost"],"card_ideas":["living-shoreline","green-grey-hybrid"],"sources":[{"title":"Miami Beach Set to Take Wraps Off Brittany Bay Park Living Shoreline","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/?p=260338","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"indian-creek-park-shoreline","title":"Indian Creek Park living shoreline","area":"collins-mid-beach","scope":"area","category":"environment","years":"2020s","summary":"Indian Creek Park pairs a waterside promenade with a living shoreline of mangroves between the old seawall and a new seawall four feet higher.","facts":["New seawall four feet higher than the existing one"],"sides":[{"who":"Designers (S&ME)","position":"Tidal flushing and mangroves create habitat while raising the edge"}],"tensions":["nature-vs-grey"],"concerns":["habitat","flooding","beach-access"],"card_ideas":["living-shoreline","green-grey-hybrid"],"sources":[{"title":"Indian Creek Park Living Shoreline","outlet":"S&ME","url":"https://smeinc.com/?p=8344","kind":"industry"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"beach-renourishment","title":"Army Corps beach renourishment","area":"collins-mid-beach","scope":"area","category":"environment","years":"2021-2025","summary":"The Army Corps placed sand along eroded Miami Beach segments under a $40.4 million contract, and the federal project was reauthorized for 50 years from 2025.","facts":["$40.4 million contract (July 2021)","About 835,000 cubic yards of sand along about 11,400 ft of shoreline"],"sides":[{"who":"Army Corps and county","position":"Renourish eroded segments; consider breakwaters and groins"}],"tensions":["nature-vs-grey","tourism-vs-residents"],"concerns":["beach-access","flooding","habitat"],"card_ideas":["living-shoreline","tourism-campaign"],"sources":[{"title":"USACE nearing completion of the Miami Beach project","outlet":"Dredging Today","url":"https://dredgingtoday.com/?p=82517","kind":"industry"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"palms-to-shade-trees","title":"Palms swapped for shade trees","area":"collins-mid-beach","scope":"area","category":"environment","years":"2021-2022","summary":"Miami Beach adopted an urban forestry plan to cut palms from about 60% of the canopy to 25% over 30 years, drawing pushback over the city's image, including a downsized plan for 41st Street.","facts":["Palms nearly 60% of the canopy; target 25%"],"sides":[{"who":"Then-Vice Mayor Steven Meiner","position":"Palm reductions could hurt the city's cultural, historical and economic brand"},{"who":"Environmental advocates","position":"Shade trees absorb more CO2 and stormwater"}],"tensions":["tourism-vs-residents"],"concerns":["habitat","heat","city-identity"],"card_ideas":["public-campaign","tourism-campaign"],"sources":[{"title":"Miami Beach climate change plan would see iconic palm trees swapped out","outlet":"CBS Miami","url":"https://www.cbsnews.com/amp/miami/news/miami-beach-climate-change-plan-iconic-palm-trees-swapped-canopy-trees","kind":"news"},{"title":"Florida cities and palm trees","outlet":"NPR","url":"https://www.npr.org/2022/01/05/1064876188/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"north-beach-oceanside-park","title":"North Beach Oceanside Park upgrade","area":"north-beach-oceanside","scope":"area","category":"environment","years":"2023","summary":"The city completed a $15.8 million upgrade of North Beach Oceanside Park and the adjoining Beachwalk, with expanded paths and new landscaping.","facts":["$15.8 million project","Net increase of 188 trees"],"sides":[{"who":"City","position":"More shade, paths and park amenities by the beach"}],"tensions":["public-benefit-swap"],"concerns":["beach-access","habitat"],"card_ideas":["public-access-guarantee","living-shoreline"],"sources":[{"title":"Miami Beach Completes $15.8 Million Upgrade to North Beach Oceanside Park","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/wp-content/uploads/2023/10/Miami-Beach-Completes-15.8-Million-Upgrade-to-North-Beach-Oceanside-Park.pdf","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"dune-management","title":"Coastal Dune Management Plan","area":"citywide","scope":"citywide","category":"environment","years":"2015","summary":"The city's Coastal Dune Management Plan aims to use the best available science to enhance the dunes' environmental and storm protection functions.","facts":["Includes a $300,000 citywide dune restoration project"],"sides":[{"who":"City","position":"Dunes are storm protection and habitat"}],"tensions":["nature-vs-grey"],"concerns":["habitat","flooding","beach-access"],"card_ideas":["living-shoreline","environmental-challenge"],"sources":[{"title":"Miami Beach Coastal Dune Management Plan (presentation)","outlet":"FSBPA","url":"https://www.fsbpa.com/2015TechPresentations/Wells.pdf","kind":"official"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"fontainebleau-water-park","title":"Fontainebleau water park","area":"collins-mid-beach","scope":"area","category":"development","years":"2025-2026","summary":"The Fontainebleau at 4441 Collins Ave proposed up to 11 water slides, one about 120 ft tall, needing 11 variances from the Historic Preservation Board. A state bill was amended to let it bypass board review, and the city moved toward suing the state. As of March 2026 no final board decision had been reported, so the outcome is unresolved.","facts":["Up to 11 slides, one about 120 ft tall","Nearly three dozen speakers opposed it at the November 2025 hearing, one spoke in favor","City Commission voted 4-1 to authorize the mayor to sue the state"],"sides":[{"who":"Mayor Steven Meiner","position":"Tallahassee is not the zoning board of Miami Beach","quote":"Tallahassee is not the zoning board of Miami Beach."},{"who":"Miami Design Preservation League","position":"A slide tower would be a visually dominant structure on the landmark"},{"who":"Fontainebleau","position":"No added traffic or density; not open to the public"}],"tensions":["growth-vs-heritage","local-vs-state"],"concerns":["height","historic-character","local-control"],"card_ideas":["hotel-development","tourism-campaign","environmental-challenge","preservation-appeal"],"sources":[{"title":"Miami Beach leaders protest state bill as Fontainebleau water park proposal draws scrutiny","outlet":"WLRN","url":"https://www.wlrn.org/development/2026-03-10/miami-beach-fontainebleau-water-park-bill-399","kind":"news"},{"title":"Our Positions at the February 10, 2026 Historic Preservation Board","outlet":"Miami Design Preservation League","url":"https://mdpl.org/news/2026/02/our-positions-at-the-february-10-2026-historic-preservation-board","kind":"advocacy"},{"title":"Fontainebleau Miami Beach water park plan could drown","outlet":"The Real Deal","url":"https://therealdeal.com/miami/2025/11/21/fontainebleau-miami-beach-water-park-plan-could-drown/","kind":"news"}],"verification":{"status":"resolved","notes":["Final board decision and case file number not found"],"resolution":"Framed as unresolved; no final decision is claimed."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"ocean-terrace-upzoning","title":"Ocean Terrace upzoning rejected","area":"north-beach-oceanside","scope":"area","category":"development","years":"2022-2023","summary":"Voters were asked to upzone the historic Ocean Terrace blocks between 73rd and 75th streets from 75 ft to 250 ft. Voters rejected the plan in November 2022, and the developer returned with a plan keeping historic facades but still including a tower.","facts":["Height limit would have risen from 75 ft (8 stories) to 250 ft (22 stories)","Developer spent more than $700,000 campaigning"],"sides":[{"who":"Developer Sandor Scher","position":"Upzoning would revitalize North Beach"},{"who":"Opponents","position":"Would destroy historic architecture and the low-rise feel"}],"tensions":["growth-vs-heritage"],"concerns":["height","historic-character","density"],"card_ideas":["hotel-development","neighborhood-petition","referendum-demand","public-campaign"],"sources":[{"title":"Ocean Terrace's future unclear after voters reject plan for 22-story condo tower","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/news/ocean-terraces-future-unclear-after-voters-reject-plan-for-22-story-condo-tower-8029149/","kind":"news"},{"title":"North Beach developer plans new luxury condo tower after losing at ballot box","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/uncategorized/north-beach-developer-plans-new-luxury-condo-tower-after-losing-at-ballot-box-8433915/","kind":"news"},{"title":"Certification of Official Results, November 8, 2022","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/wp-content/uploads/2022/11/Certification-of-Official-Results-Bates.pdf","kind":"official"}],"verification":{"status":"resolved","notes":["Vote share comes from one secondary source; confirm against certified results"],"resolution":"Dropped the single-source vote percentage; linked the city's certified results for the outcome."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"north-beach-resort-overlay","title":"North Beach Oceanside Resort Overlay ballot","area":"north-beach-oceanside","scope":"area","category":"development","years":"2022","summary":"A November 2022 ballot question asked voters to raise the floor area ratio on oceanfront lots at 6605-6757 Collins Avenue, because the City Charter requires a vote for FAR increases.","facts":["FAR from 2.25 to 3.0, with incentives up to 4.5 for qualifying 