n-propertys-future-remains-uncertain","kind":"news"},{"title":"Miami Beach's fabled Deauville Beach Resort imploded","outlet":"The Architect's Newspaper","url":"https://www.archpaper.com/2022/11/miami-beach-fabled-deauville-beach-resort-imploded-future-redevelopment-plans-unsettled/?amp=1","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"clevelander-live-local","title":"Clevelander tower under the Live Local Act","area":"new-area","scope":"new-area","category":"development","years":"2023-2024","summary":"The Clevelander's owner proposed a 30-story tower on Ocean Drive under Florida's Live Local Act, then filed an 18-story plan with affordable units after an outcry. Ocean Drive heights are otherwise limited to 50 ft.","facts":["Revised to 18 stories with 137 units, 55 affordable","Ocean Drive height limit of 50 ft"],"sides":[{"who":"Then-Mayor Dan Gelber","position":"A tragic idea"},{"who":"Developer Jesta Group","position":"Workforce housing under state law"}],"tensions":["growth-vs-heritage","local-vs-state"],"concerns":["height","affordability","historic-character"],"card_ideas":["hotel-development","live-local-bypass","preservation-appeal"],"sources":[{"title":"Tragic idea, Miami Beach Mayor on plans to turn iconic Clevelander Hotel into high-rise","outlet":"CBS Miami","url":"https://www.cbsnews.com/amp/miami/news/plans-to-turn-clevelander-into-high-rise-upsetting-many/","kind":"news"}],"verification":{"status":"conflict","notes":["No status found after 2024"]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"live-local-workforce-housing","title":"Live Local Act and workforce housing","area":"citywide","scope":"citywide","category":"housing","years":"2023-2025","summary":"Florida's Live Local Act lets developers bypass local zoning if at least 40% of units are workforce or affordable housing. Miami Beach wants workers living locally without losing its character, and a report found the law still misses many public-sector workers.","facts":["At least 40% of units at 80% to 120% of area median income"],"sides":[{"who":"Commissioner Alex Fernandez","position":"Large towers along Alton Road would hurt tourism and workers' quality of life"},{"who":"Florida Policy Institute","position":"Not enough affordable housing for sole-earner firefighters, teachers and police"}],"tensions":["local-vs-state"],"concerns":["affordability","height","local-control"],"card_ideas":["live-local-bypass","neighborhood-petition"],"sources":[{"title":"Miami Beach Wants Workers Living Local Without Giving In To Live Local Act","outlet":"Bisnow","url":"https://www.bisnow.com/news/south-florida/construction-development/miami-beach-wants-to-keep-workforce-local-without-losing-character-130953","kind":"news"},{"title":"Report reveals Florida's workforce housing is unaffordable for many public sector workers","outlet":"WLRN","url":"https://www.wlrn.org/government-politics/2024-11-15/report-reveals-floridas-workforce-housing-is-unaffordable-for-many-public-sector-workers","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"ritz-carlton-tower","title":"Ritz-Carlton South Beach condo addition","area":"new-area","scope":"new-area","category":"development","years":"2023","summary":"The Historic Preservation Board approved a 15-story condo addition at the Ritz-Carlton South Beach despite objections that the tower was out of character and would shade the beach.","facts":["15-story, 182-foot tower"],"sides":[{"who":"Critics","position":"Out of character and would shadow the beach"},{"who":"Owners","position":"Won approval for the addition"}],"tensions":["growth-vs-heritage"],"concerns":["height","beach-access","historic-character"],"card_ideas":["hotel-development","preservation-appeal"],"sources":[{"title":"Owners of South Beach's Ritz-Carlton Win Approval to Add 15-Story Condo","outlet":"Commercial Observer","url":"https://commercialobserver.com/2023/10/ritz-carlton-south-beach-lincoldn-road/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"five-hundred-alton","title":"500-700 Alton tower and Park on Fifth","area":"south-pointe","scope":"area","category":"development","years":"2018-2019","summary":"The city approved a tall tower at the South Beach gateway at 500-700 Alton Road in exchange for a developer-donated 3-acre public park, with a pedestrian bridge funded by the 2018 GO Bond.","facts":["Tower over 500 ft (sources give 519 ft and 553 ft)","3-acre park donated to the city","$10 million GO Bond for the bridge"],"sides":[{"who":"City Commission","position":"Height traded for a public park"},{"who":"Developer Russell Galbut","position":"Builds and donates the park"}],"tensions":["public-benefit-swap"],"concerns":["height","parks","density"],"card_ideas":["public-benefit-swap","hotel-development","public-access-guarantee"],"sources":[{"title":"Beach commission to hear 44-story limit on Alton Road site","outlet":"Miami Today","url":"https://www.miamitodaynews.com/breaking/beach-commission-hear-44-story-limit-alton-road-site/","kind":"news"},{"title":"Crescent Heights reveals new renderings of Park on Fifth","outlet":"Profile Miami","url":"https://profilemiamire.com/miamirealestate/2019/12/12/crescent-heights-reveals-new-renderings-of-park-coming-to-500-alton-in-south-beach","kind":"news"}],"verification":{"status":"resolved","notes":["Sources disagree on tower height (519 ft vs 553 ft)"],"resolution":"Height stated as over 500 ft with both reported figures named."},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"convention-center-hotel","title":"Convention Center hotel referendums","area":"new-area","scope":"new-area","category":"development","years":"2016-2018","summary":"A 2016 convention center hotel plan failed at the ballot over size and traffic. A smaller 800-room plan passed in 2018, clearing the 60 percent required.","facts":["2016 plan got 54 percent","2018 plan got about 64 percent; 60 percent needed","800 rooms, 185 ft"],"sides":[{"who":"Developers","position":"Hotel supports the convention center"},{"who":"2016 opponents","position":"Too big, too much traffic"}],"tensions":["public-benefit-swap","tourism-vs-residents"],"concerns":["height","traffic","economy"],"card_ideas":["hotel-development","referendum-demand","tourism-campaign"],"sources":[{"title":"Voters approve Miami Beach convention center hotel","outlet":"Terra Group (reprint)","url":"https://terragroup.com/voters-approve-miami-beach-convention-center-hotel","kind":"industry"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"art-deco-district-1979","title":"Art Deco District listed (1979)","area":"citywide","scope":"citywide","category":"heritage","years":"1976-1979","summary":"Barbara Baer Capitman and the Miami Design Preservation League campaigned with vigils and protests to list the Art Deco District on the National Register in 1979, though some buildings were still lost.","facts":["Listed May 14, 1979","First 20th-century district on the National Register"],"sides":[{"who":"Barbara Baer Capitman","position":"Stood in front of bulldozers to save the district"},{"who":"Developers of the era","position":"Demolished the Senator and New Yorker hotels"}],"tensions":["growth-vs-heritage"],"concerns":["historic-character"],"card_ideas":["preservation-appeal","public-campaign"],"sources":[{"title":"Barbara Baer Capitman: South Beach's Art Deco Hero","outlet":"National Trust (Saving Places)","url":"https://savingplaces.org/stories/barbara-baer-capitman-south-beach-art-deco-hero","kind":"advocacy"},{"title":"Miami Beach Deco","outlet":"PBS American Experience","url":"https://www.pbs.org/wgbh/americanexperience/features/miami-beach-deco/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"alton-bayfront-overlay","title":"Alton Beach Bayfront Overlay density","area":"west-avenue","scope":"area","category":"development","years":"2025","summary":"A June 2025 commission meeting reportedly considered a higher-density residential category on the Alton bayfront tied to public benefits.","facts":["Density tied to public benefits"],"sides":[{"who":"Commission","position":"Density for public benefits"},{"who":"Concerned voices","position":"State law could affect voter control over FAR"}],"tensions":["public-benefit-swap","local-vs-state"],"concerns":["density","local-control"],"card_ideas":["public-benefit-swap","referendum-demand"],"sources":[{"title":"Miami Beach Commission votes on two major development items amid legal concerns","outlet":"Soar (AI summary)","url":"https://cp.soar.com/articles/5096489/Miami-Beach/Miami-Dade-County/Florida/Miami-Beach-Commission-votes-on-two-major-development-items-amid-legal-concerns","kind":"other"}],"verification":{"status":"conflict","notes":["Only source is an AI-generated summary; verify against commission minutes or drop"]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"ocean-drive-traffic","title":"Ocean Drive closed to cars, then reopened","area":"new-area","scope":"new-area","category":"mobility","years":"2020-2025","summary":"Ocean Drive closed to cars in 2020, partly reopened in 2022 with a bike lane, and after a Clevelander lawsuit a judge ordered two-way traffic restored; the bike lanes came out in 2025.","facts":["Closed to cars in May 2020","Reopened to two-way traffic in February 2025"],"sides":[{"who":"Clevelander and hotel owners","position":"The pedestrian plaza hurt business and safety"},{"who":"Bike and pedestrian advocates","position":"Removing bike lanes is a setback"},{"who":"Mayor","position":"Called the judge's decision outrageous"}],"tensions":["tourism-vs-residents"],"concerns":["traffic","safety","business-impact"],"card_ideas":["public-access-guarantee","tourism-campaign","neighborhood-petition"],"sources":[{"title":"Miami Beach reopens Ocean Drive to two-way vehicle traffic, removing bike lanes","outlet":"WLRN","url":"https://www.wlrn.org/news-in-brief/2025-02-07/miami-beach-reopens-ocean-drive-to-two-way-vehicle-traffic-removing-bike-lanes","kind":"news"},{"title":"Ocean Drive reopens to two-way traffic after Clevelander lawsuit","outlet":"NBC Miami","url":"https://www.nbcmiami.com/news/local/ocean-drive-reopens-to-2-way-traffic-removes-bike-lanes-after-clevelander-lawsuit/3538279/?amp=1","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"spring-break-curfew-2024","title":"Spring break curfew","area":"south-pointe","scope":"area","category":"quality-of-life","years":"2023-2024","summary":"After two fatal shootings in 2023, Miami Beach set a weekend curfew south of 23rd Street in March 2024, limited beach access and closed liquor stores early under its Break Up with Spring Break campaign.","facts":["Curfew from 11:59 p.m. Friday to 6 a.m. Monday south of 23rd Street"],"sides":[{"who":"City","position":"Protecting public safety"},{"who":"Commissioner Ricky Arriola","position":"Panic-stricken politicians reacting rather than planning"},{"who":"Business owners","position":"A lockdown means no business"}],"tensions":["tourism-vs-residents"],"concerns":["safety","business-impact","beach-access"],"card_ideas":["tourism-campaign","neighborhood-petition","public-access-guarantee"],"sources":[{"title":"Miami Beach enacts emergency curfew amid spring break crackdown","outlet":"Local10","url":"https://local10.com/news/local/2024/03/15/miami-beach-enacts-emergency-curfew-amid-spring-break-crackdown","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"short-term-rental-ban","title":"Short-term rental ban and fines","area":"citywide","scope":"citywide","category":"housing","years":"2016-2020","summary":"Short-term rentals are illegal in most Miami Beach neighborhoods. Fines starting at $20,000 were struck down, then restructured; the city collected only a fraction of what it levied.","facts":["Fines of $20,000 up to $100,000 from 2016","About $8 million in fines issued, about $500,000 collected"],"sides":[{"who":"City","position":"Rentals hurt quality of life in neighborhoods"},{"who":"Home-sharing companies","position":"Rentals support the local economy"}],"tensions":["tourism-vs-residents"],"concerns":["affordability","quality-of-life","economy"],"card_ideas":["neighborhood-petition","tourism-campaign"],"sources":[{"title":"Part of Miami Beach short-term rental law still valid, court rules","outlet":"Avalara","url":"https://www.avalara.com/mylodgetax/en/blog/2020/10/part-of-miami-beach-short-term-rental-law-still-valid-court-rules-in-reversal.html","kind":"industry"},{"title":"Miami Beach has collected only 2 percent of short-term rental fines","outlet":"Miami New Times","url":"https://www.miaminewtimes.com/news/miami-beach-has-collected-just-two-percent-of-5-million-in-short-term-rental-fines-9242368/","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"surfside-aftermath","title":"After Surfside: unsafe buildings and recertification costs","area":"citywide","scope":"citywide","category":"housing","years":"2021-2024","summary":"After the 2021 Surfside collapse, dozens of South Florida buildings were vacated as unsafe, many in Miami Beach, and Florida's recertification law raised costs and special assessments for condo owners.","facts":["At least 26 buildings vacated, 18 in Miami Beach","Recertification at 25 years within 3 miles of the coast, then every 10 years"],"sides":[{"who":"Condo owners","position":"Special assessments force some to pay up or move out"},{"who":"State","position":"Recertification keeps buildings safe"}],"tensions":["costs-on-owners"],"concerns":["safety","affordability","cost"],"card_ideas":["elevate-buildings","emergency-funding"],"sources":[{"title":"At least 26 buildings deemed unsafe, evacuated since Surfside","outlet":"NBC Miami","url":"https://www.nbcmiami.com/news/local/surfside-condo-collapse/at-least-26-buildings-in-south-florida-deemed-unsafe-evacuated-since-surfside-condo-collapse/3059035/?amp=1","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"go-bond-2018","title":"2018 General Obligation Bond","area":"citywide","scope":"citywide","category":"budget","years":"2018-2026","summary":"Voters approved a $439 million GO Bond in 2018 for 57 projects across parks, neighborhoods and infrastructure, and public safety, issued in tranches over a decade.","facts":["$439 million for 57 projects","$169M parks and culture, $198M neighborhoods and infrastructure, $72M public safety","Each measure passed with about 70 percent"],"sides":[{"who":"Voters","position":"Approved all three measures"}],"tensions":["budget-tradeoff","public-benefit-swap"],"concerns":["cost","parks","flooding"],"card_ideas":["emergency-funding","public-campaign"],"sources":[{"title":"GO Bond Program","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/de/egovapp/city-hall/gobonddepartment/","kind":"official"},{"title":"Miami Beach G.O. Bond coverage","outlet":"Miami Today","url":"https://www.miamitodaynews.com/?p=57734","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"},{"id":"72nd-street-complex","title":"72nd Street community complex","area":"north-beach-oceanside","scope":"area","category":"budget","years":"2018-2026","summary":"North Beach's GO Bond complex (park, library, pools, garage) grew in cost and drew resident objections to a rooftop Olympic pool and to moving the library, which needs a referendum.","facts":["$53.8 million GO Bond, about $107 million all-in","50-meter pool on top of a 500-space garage"],"sides":[{"who":"Resident-hired engineers","position":"A rooftop Olympic pool has never been done and is a weight hazard"},{"who":"Residents","position":"Library land cannot be sold without a referendum"}],"tensions":["budget-tradeoff","public-benefit-swap"],"concerns":["cost","parks","safety"],"card_ideas":["referendum-demand","neighborhood-petition","emergency-funding"],"sources":[{"title":"72 Street Community Complex","outlet":"City of Miami Beach","url":"https://www.miamibeachfl.gov/projects/72-street-community-complex/","kind":"official"},{"title":"Miami Beach Planning $107M Project With Olympic Pool Atop Parking Garage","outlet":"Bisnow","url":"https://www.bisnow.com/news/south-florida/architecture-design/miami-beach-olympic-pool-parking-garage-110238","kind":"news"}],"verification":{"status":"sources-checked","notes":[]},"review_status":"unreviewed","retrieved_at":"2026-10-11"}]$$))) i, TABLE(FLATTEN(INPUT => i.value:sources)) s;

CREATE OR REPLACE VIEW COASTAL_CLASH.CORPUS.APPROVED_ISSUES AS
   SELECT i.*, (SELECT ARRAY_AGG(OBJECT_CONSTRUCT('title', s.TITLE, 'outlet', s.OUTLET, 'url', s.URL, 'kind', s.KIND))
                FROM COASTAL_CLASH.CORPUS.SOURCES s WHERE s.ISSUE_ID = i.ID) AS SOURCES
   FROM COASTAL_CLASH.CORPUS.ISSUES i WHERE i.REVIEW_STATUS = 'approved';

SELECT REVIEW_STATUS, VERIFICATION:status::STRING AS VERIFICATION, COUNT(*) AS ISSUES FROM COASTAL_CLASH.CORPUS.ISSUES GROUP BY 1, 2 ORDER BY 1, 2;
